create table if not exists public.powerhouse_resource_factors (id uuid primary key default gen_random_uuid(), factor_id text not null unique, resource_type text not null, unit text not null, quantity_basis numeric not null check (quantity_basis > 0), energy_kwh numeric, co2e_kg numeric, water_liters numeric, methodology text not null, confidence numeric not null default 0 check (confidence >= 0 and confidence <= 1), valid_from date not null, valid_to date, created_at timestamptz not null default now()); alter table public.powerhouse_resource_factors enable row level security;
